--- 函数耗时统计工具
---

local _M = {}
_M.name = ""
_M.startTime = 0
_M.totalTime = 0
_M.stepTime = 0
_M.stepRecord = {}
_M.openSign = false       -- 全局控制统计开关

function _M.timeNow()
    ngx.update_time()
    return ngx.now()
end

function _M:Start(name)
    if not self.openSign then
        return nil
    end

    local o = {}
    setmetatable(o, self)
    self.__index = self

    o.name = name
    o.startTime = self.timeNow()
    o.stepTime = o.startTime
    o.stepRecord = {}
    return o
end

function _M:StepEnd(stepName)
    if not self then
        return
    end

    local now = self.timeNow()
    local time = now - self.stepTime
    self.stepTime = now
    self.stepRecord[#self.stepRecord + 1] = "[".. stepName .. ":    " .. tostring(time * 1000) .."]"
end

function _M:Stop()
    if not self then
        return
    end
    self.totalTime = self.timeNow() - self.startTime
end

function _M:PrintStr()
    if not self then
        return ""
    end

    local ptStr = " StopWatch:" .. self.name ..
            ", total(ms):" .. tostring(self.totalTime * 1000)
    for _,v in ipairs(self.stepRecord) do
        ptStr = ptStr .. " -- step:" .. v
    end
    -- ptStr = ptStr .. "\n------------------------"
    return ptStr
end

return _M